//! Rev.12 attempt_discovery shortlist benchmark
//!
//! Quantifies the speedup from bounding structure-mapping work at K
//! candidates per RARE node (Claim 36-41 / 47-48 input-output behaviour
//! preserved; only the simple-distance pre-screening cap of Claim 46 is
//! changed from a percentage to an absolute size).
//!
//! Methodology
//!   - synthetic deterministic graphs at n_pool ∈ {1_000, 10_000}
//!   - n_rare = 50 RARE nodes generated by single-edge attachment to hub
//!   - settings: K ∈ {10, 100, 1_000, usize::MAX (no cap)}
//!   - reference for recall@1 = analogy target chosen at K=usize::MAX
//!   - measure: wall-clock for n_rare attempt_discovery calls
//!
//! Run: `cargo run --release -p cgb-kdf --example rev12_shortlist_benchmark`

use cgb_kdf::framework::KdfProcessorRev12;
use std::collections::HashMap;
use std::time::Instant;

fn build_graph(n_pool: usize, n_rare: usize, seed: u64) -> (usize, Vec<(u32, u32, f64)>) {
    // Deterministic synthetic graph:
    //   - node 0 is a CORE hub connected to first ~30% of nodes
    //   - middle nodes form an EDGE ring
    //   - last n_rare nodes attach to hub via a single edge (RARE candidates)
    let mut edges = Vec::with_capacity(n_pool * 2);
    let core_hub = 0u32;
    let core_count = (n_pool as f64 * 0.3) as u32;
    for i in 1..core_count {
        edges.push((core_hub, i, 1.0));
    }
    // EDGE ring among the middle band
    for i in core_count..(n_pool as u32 - n_rare as u32) {
        edges.push((i, i + 1, 1.0));
    }
    // RARE attachments — single-edge to hub
    for r in (n_pool as u32 - n_rare as u32)..n_pool as u32 {
        edges.push((core_hub, r, 1.0));
    }
    // Inject deterministic salt so different seeds yield different ego graphs
    let salt = (seed % 7) as u32;
    if salt > 0 && core_count > salt {
        edges.push((salt, salt + 1, 0.5));
    }

    let total_nodes = n_pool;
    (total_nodes, edges)
}

#[derive(Debug, Clone)]
struct RunResult {
    k_setting: String,
    elapsed_ms: f64,
    rare_processed: usize,
    targets: HashMap<u32, Option<u32>>,
}

fn run_one(n_pool: usize, n_rare: usize, k: usize, label: &str, seed: u64) -> RunResult {
    let (n, edges) = build_graph(n_pool, n_rare, seed);
    let mut p = KdfProcessorRev12::default();
    p.set_shortlist_top_k(k);
    p.initialize(n, &edges);

    let rares: Vec<u32> = p.get_original_rare_nodes();
    let mut targets: HashMap<u32, Option<u32>> = HashMap::new();

    let start = Instant::now();
    for &r in &rares {
        let _ = p.attempt_discovery(r);
        targets.insert(r, p.get_rare_state(r).and_then(|s| s.analogy_target));
    }
    let elapsed = start.elapsed().as_secs_f64() * 1000.0;

    RunResult {
        k_setting: label.to_string(),
        elapsed_ms: elapsed,
        rare_processed: rares.len(),
        targets,
    }
}

fn recall_at_one(opt: &RunResult, reference: &RunResult) -> f64 {
    if reference.targets.is_empty() {
        return 1.0;
    }
    let hits = reference
        .targets
        .iter()
        .filter(|(node, ref_target)| opt.targets.get(node) == Some(*ref_target))
        .count();
    hits as f64 / reference.targets.len() as f64
}

fn main() {
    println!("================================================================================");
    println!("Rev.12 attempt_discovery shortlist benchmark");
    println!("    Quantifies speedup from K-bounded structure-mapping (Claim 46 cap form)");
    println!("    Claim 36-41 / 47-48 input-output behaviour is preserved.");
    println!("================================================================================");

    // (n_pool, n_rare_target, seed, run_full_baseline)
    //   run_full_baseline=false skips the K=∞ run for very large pools where
    //   the unbounded baseline is impractical; speedup is then reported
    //   relative to the largest measured K (e.g. K=1000) and recall@1 vs
    //   the K=1000 reference (which itself preserves recall vs K=∞).
    let scenarios: &[(usize, usize, u64, bool)] = &[
        (1_000, 50, 42, true),
        (10_000, 50, 42, true),
        (100_000, 50, 42, false),
    ];

    for &(n_pool, n_rare, seed, run_baseline) in scenarios {
        println!(
            "\n=== n_pool = {} | n_rare target = {} | seed = {} | full baseline: {} ===",
            n_pool, n_rare, seed, run_baseline
        );
        println!(
            "{:<28}{:>14}{:>14}{:>14}{:>14}",
            "setting", "wall (ms)", "rares", "speedup", "recall@1"
        );

        let mut k_settings: Vec<(usize, &str)> =
            vec![(10, "K=10"), (100, "K=100 (default)"), (1_000, "K=1000")];
        if run_baseline {
            k_settings.push((usize::MAX, "K=∞ (no cap, baseline)"));
        }

        // The reference run determines both the speedup denominator and the
        // recall@1 ground-truth target set.
        let reference = if run_baseline {
            run_one(n_pool, n_rare, usize::MAX, "K=∞", seed)
        } else {
            run_one(n_pool, n_rare, 1_000, "K=1000 (proxy ref)", seed)
        };
        let ref_ms = reference.elapsed_ms;

        let mut rows: Vec<(String, f64, usize, f64, f64)> = Vec::new();
        for &(k, label) in &k_settings {
            let r = run_one(n_pool, n_rare, k, label, seed);
            let speedup = if r.elapsed_ms > 0.0 {
                ref_ms / r.elapsed_ms
            } else {
                f64::INFINITY
            };
            let recall = recall_at_one(&r, &reference);
            rows.push((
                r.k_setting.clone(),
                r.elapsed_ms,
                r.rare_processed,
                speedup,
                recall,
            ));
        }

        for (label, ms, rares, speedup, recall) in rows {
            println!(
                "{:<28}{:>14.2}{:>14}{:>13.2}x{:>13.1}%",
                label,
                ms,
                rares,
                speedup,
                recall * 100.0
            );
        }

        if !run_baseline {
            println!(
                "  (note: K=∞ skipped at n_pool={} due to wall-time; speedup is vs K=1000 proxy)",
                n_pool
            );
        }
    }

    println!("\n================================================================================");
    println!("Interpretation");
    println!("================================================================================");
    println!("  speedup = (K=∞ wall) / (K-setting wall)");
    println!("  recall@1 = fraction of RARE nodes whose chosen analogy target equals the");
    println!("             K=∞ baseline target. K=100 default should hold ≥99% recall while");
    println!("             delivering substantial wall-clock speedup at large pool sizes.");
}
